mapper.select:
SELECT vu.id, vu.username, vu.real_name as realName, vu.phone, vu.email, vu.id_card as idCard, CASE vu.gender WHEN 1 THEN '男' WHEN 2 THEN '女' ELSE '未知' END as genderText, vu.age, vu.address, CASE vu.status WHEN 1 THEN '正常' WHEN 0 THEN '禁用' ELSE '未知' END as statusText, vu.status, -- 等级字段已屏蔽，改为使用星级字段 -- CASE -- WHEN COALESCE(vs.total_service_hours, 0) >= 500 THEN '专家' -- WHEN COALESCE(vs.total_service_hours, 0) >= 200 THEN '高级' -- WHEN COALESCE(vs.total_service_hours, 0) >= 50 THEN '中级' -- ELSE '初级' -- END as level, -- CASE -- WHEN COALESCE(vs.total_service_hours, 0) >= 500 THEN 4 -- WHEN COALESCE(vs.total_service_hours, 0) >= 200 THEN 3 -- WHEN COALESCE(vs.total_service_hours, 0) >= 50 THEN 2 -- ELSE 1 -- END as levelValue, COALESCE(vu.total_service_hours, 0) as totalServiceHours, COALESCE(vs.activity_count, 0) as activityCount, COALESCE(vu.total_points, 0) as totalPoints, vu.star_level as starLevel, vu.star_rating_time as starRatingTime, vu.created_time as createdTime, vu.last_login_time as lastLoginTime FROM volunteer_user vu LEFT JOIN ( SELECT user_id, COUNT(DISTINCT activity_id) as activity_count FROM service_record WHERE deleted = 0 GROUP BY user_id ) vs ON vu.id = vs.user_id WHERE vu.deleted = 0
AND ( vu.real_name LIKE CONCAT('%', #{query.keyword}, '%') OR vu.username LIKE CONCAT('%', #{query.keyword}, '%') OR vu.email LIKE CONCAT('%', #{query.keyword}, '%') )
AND vu.status = #{query.status}
AND vu.gender = #{query.gender}
AND vu.star_level = #{query.starLevel}
AND vu.address LIKE CONCAT('%', #{query.region}, '%')
AND vu.age >= #{query.minAge}
AND vu.age <= #{query.maxAge}
AND COALESCE(vu.total_service_hours, 0) >= #{query.minServiceHours}
AND COALESCE(vu.total_service_hours, 0) <= #{query.maxServiceHours}
AND vu.created_time >= #{query.registerTimeStart}
AND vu.created_time <= #{query.registerTimeEnd}
ORDER BY COALESCE(vu.total_service_hours, 0) ${query.sortOrder}
ORDER BY COALESCE(vs.activity_count, 0) ${query.sortOrder}
ORDER BY COALESCE(vu.total_points, 0) ${query.sortOrder}
ORDER BY vu.created_time ${query.sortOrder}
ORDER BY vu.id ${query.sortOrder}
ORDER BY vu.id ASC

